package dev.aragonite.powersync.client;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
final class ServerClient {
 static JSONObject redeem(String base,String code,String installation,String nativeDevice,String nativeUid)throws Exception {JSONObject body=new JSONObject().put("code",code).put("installationId",installation).put("nativeDeviceId",nativeDevice).put("model",android.os.Build.MODEL).put("nativeUid",nativeUid).put("preserveNativeIdentity",true);return request(base+"/api/v1/boox/enroll","POST",body,null);}
 static JSONObject request(String url,String method,JSONObject body,String token)throws Exception {return request(url,method,body,token,262144);}
 static JSONObject request(String url,String method,JSONObject body,String token,int limit)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();if(!"https".equals(c.getURL().getProtocol()))throw new IOException("HTTPS required");c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);try{if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();if(status==409){if(!url.endsWith("/api/v1/boox/enroll"))throw new IOException("Server data changed or recovery is unavailable; refresh and review again");try(InputStream error=c.getErrorStream()){if(error!=null){byte[] raw=error.readNBytes(4096);JSONObject detail=new JSONObject(new String(raw,StandardCharsets.UTF_8));if("native_identity_required".equals(detail.optString("error")))throw new IOException("Sign in to your BOOX account in native Settings before connecting the first device. Your existing library identity is needed.");}}throw new IOException("This server is linked to a different BOOX account. Return to your previous server and use the matching library.");}if(status<200||status>=300)throw new IOException("Server returned HTTP "+status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Server reply exceeds limit");out.write(b,0,n);}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}finally{c.disconnect();}}
}
